/* ============================================================
   PATCH v1.3.5 — Фикс визуального отображения сотрудников в дереве гипотез
   ============================================================ */

/* Сетка для списка сотрудников: аккуратные колонки, нормальные отступы */
#taskModal .hyp-people-list {
    display: grid !important;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)) !important;
    gap: 6px 12px !important;
    max-height: 200px !important;
    overflow-y: auto !important;
    padding: 10px !important;
    border: 1px solid var(--trk-card-border) !important;
    border-radius: 8px !important;
    background: var(--trk-input-bg) !important;
    box-sizing: border-box !important;
}

/* Контейнер одного сотрудника (label) */
#taskModal .hyp-person {
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
    font-size: 0.82rem !important;
    cursor: pointer !important;
    padding: 4px 6px !important;
    border-radius: 6px !important;
    background: transparent !important;
    border: 1px solid transparent !important;
    margin: 0 !important;
    width: 100% !important;
    box-sizing: border-box !important;
    transition: background 0.15s, border-color 0.15s !important;
}

#taskModal .hyp-person:hover {
    background: var(--trk-hover-row) !important;
    border-color: var(--trk-card-border) !important;
}

/* ЖЕСТКИЙ ФИКС ЧЕКБОКСА: снимаем унаследованные width:100%, padding и огромные размеры */
#taskModal .hyp-person input[type="checkbox"] {
    appearance: auto !important;
    -webkit-appearance: checkbox !important;
    width: 16px !important;
    height: 16px !important;
    min-width: 16px !important;
    min-height: 16px !important;
    max-width: 16px !important;
    max-height: 16px !important;
    margin: 0 !important;
    padding: 0 !important;
    flex-shrink: 0 !important;
    accent-color: var(--trk-accent, #f5d76e) !important;
    cursor: pointer !important;
    border-radius: 3px !important;
}

/* Точка цвета сотрудника */
#taskModal .hyp-dot {
    width: 10px !important;
    height: 10px !important;
    border-radius: 50% !important;
    display: inline-block !important;
    flex-shrink: 0 !important;
    box-shadow: 0 0 6px currentColor !important;
}

/* Текст ФИО: не даем переноситься на 3 строки, обрезаем с троеточием */
#taskModal .hyp-person span:last-child {
    flex: 1 !important;
    min-width: 0 !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    color: var(--trk-text) !important;
    line-height: 1.2 !important;
}

/* Заголовок «Ответственные:» над списком */
#taskModal .hyp-people-label {
    font-size: 0.75rem !important;
    color: var(--trk-meta) !important;
    text-transform: uppercase !important;
    letter-spacing: 0.5px !important;
    font-weight: 700 !important;
    margin: 10px 0 6px 0 !important;
}

/* Светлая тема */
body.trk-theme-light #taskModal .hyp-people-list {
    background: #ffffff !important;
    border-color: rgba(0,0,0,0.15) !important;
}
body.trk-theme-light #taskModal .hyp-person:hover {
    background: #f0f2f4 !important;
    border-color: rgba(0,0,0,0.10) !important;
}
